def make_part(question, status, answer=None, sources=None, missing_material=None):
    return {
        "question": question,
        "status": status,
        "answer": answer,
        "sources": list(sources or []),
        "missing_material": list(missing_material or []),
    }

from schemas import make_part


def answer_parts(parts, retrieve, generate):
    questions = list(parts)
    result_parts = []
    supported = 0

    for question in questions:
        sources = retrieve(question)
        if sources:
            supported += 1
            result_parts.append(
                make_part(question, "answered", generate(question, sources), sources)
            )
        else:
            result_parts.append(
                make_part(
                    question,
                    "insufficient_evidence",
                    None,
                    [],
                    ["No evidence was retrieved for this subquestion."],
                )
            )

    if supported == len(questions) and questions:
        status = "answered"
    elif supported == 0:
        status = "insufficient_evidence"
    else:
        status = "partial"

    return {"status": status, "parts": result_parts}
